const stampAbyssalSightingsDeparted = `-- name: StampAbyssalSightingsDeparted :exec
UPDATE abyssal_sightings s
SET departed_at = $1::timestamptz,
    depart_kind = $2::text,
    bid_count = (SELECT COUNT(*) FROM pub_contract_bids b
                 WHERE b.contract_id = s.contract_id),
    top_bid = (SELECT MAX(b.amount) FROM pub_contract_bids b
               WHERE b.contract_id = s.contract_id)
WHERE s.contract_id = ANY($3::bigint[])
  AND s.departed_at IS NULL
`

type StampAbyssalSightingsDepartedParams struct {
	DepartedAt  time.Time `json:"departed_at"`
	DepartKind  string    `json:"depart_kind"`
	ContractIds []int64   `json:"contract_ids"`
}

// The departure stamp also snapshots the listing's bid
// state (an auction's rows in pub_contract_bids, counted
// before the completion step deletes them): an exit with
// bids on it is a different fact from an exit without.
func (q *Queries) StampAbyssalSightingsDeparted(ctx context.Context, arg StampAbyssalSightingsDepartedParams) error {
	_, err := q.db.ExecContext(ctx, stampAbyssalSightingsDeparted, arg.DepartedAt, arg.DepartKind, pq.Array(arg.ContractIds))
	return err
}

const upsertAbyssalItem = `-- name: UpsertAbyssalItem :exec
INSERT INTO abyssal_items (
    item_id, type_id, source_type_id, mutator_type_id, created_by,
    attributes, fetched_at, first_seen_at, last_seen_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $8)
ON CONFLICT (item_id) DO UPDATE SET
    last_seen_at = excluded.last_seen_at
`

type UpsertAbyssalItemParams struct {
	ItemID        int64           `json:"item_id"`
	TypeID        int64           `json:"type_id"`
	SourceTypeID  int64           `json:"source_type_id"`
	MutatorTypeID int64           `json:"mutator_type_id"`
	CreatedBy     int64           `json:"created_by"`
	Attributes    json.RawMessage `json:"attributes"`
	FetchedAt     time.Time       `json:"fetched_at"`
	FirstSeenAt   time.Time       `json:"first_seen_at"`
}

// An instance's rolls never change: the first fetch is the
// row; later sightings of the same instance only move
// last_seen_at.
func (q *Queries) UpsertAbyssalItem(ctx context.Context, arg UpsertAbyssalItemParams) error {
	_, err := q.db.ExecContext(ctx, upsertAbyssalItem,
		arg.ItemID,
		arg.TypeID,
		arg.SourceTypeID,
		arg.MutatorTypeID,
		arg.CreatedBy,
		arg.Attributes,
		arg.FetchedAt,
		arg.FirstSeenAt,
	)
	return err
}

